/// The commit the cells' source came from and whether the tree is dirty: the
/// named `source_sha` of a Git-less snapshot (clean by construction), else
/// what Git reports for the checkout at `root`.
fn source_identity(root: &Path, source_sha: Option<&str>) -> Result<(String, bool), String> {
    match source_sha {
        Some(sha) => {
            validate_source_snapshot(root, sha)?;
            Ok((sha.to_string(), false))
        }
        None => Ok((
            git(root, &["rev-parse", "HEAD"])?,
            !git(root, &["status", "--porcelain", "--untracked-files=no"])?.is_empty(),
        )),
    }
}

/// A `--source-sha` must name one commit exactly: 40 lowercase hex digits, the
/// spelling `git rev-parse HEAD` records in `hermit_sha`.
pub fn validate_source_sha(sha: &str) -> Result<(), String> {
    if sha.len() == 40
        && sha
            .bytes()
            .all(|byte| matches!(byte, b'0'..=b'9' | b'a'..=b'f'))
    {
        Ok(())
    } else {
        Err(format!(
            "--source-sha must be a full 40-digit lowercase commit sha, got {sha:?}; \
             pass the output of `git rev-parse HEAD` for the archived commit"
        ))
    }
}

/// A `--source-sha` names the commit of a Git-less snapshot at `root`, which
/// is then recorded as clean. A directory holding files Git tracks is refused:
/// Git reports their commit and whether they are dirty, and the name would
/// override both. A root with no `.git` at or above it (an RE worker's input
/// tree, whether or not git is installed there) is accepted, and so is a
/// snapshot extracted inside a checkout but not tracked by it
/// (ci/buck-e2e/staged/src). Inside a checkout, a git that cannot answer
/// (a corrupt index, an unusable `.git`, no git to run) is refused: the files
/// might be tracked. The search for `.git` starts from the resolved root, so
/// a symlink to tracked files is looked up where the files are.
pub fn validate_source_snapshot(root: &Path, sha: &str) -> Result<(), String> {
    validate_source_sha(sha)?;
    let resolved = std::fs::canonicalize(root).map_err(|error| {
        format!(
            "cannot resolve --repo-root {}: {error}; pass an existing directory",
            root.display()
        )
    })?;
    if !resolved
        .ancestors()
        .any(|dir| dir.join(".git").symlink_metadata().is_ok())
    {
        return Ok(());
    }
    let tracked = crate::git_environment::git_command()
        .arg("-C")
        .arg(root)
        .args(["ls-files", "--error-unmatch", "--", "."])
        .stdout(Stdio::null())
        .stderr(Stdio::piped())
        .output();
    match tracked {
        // `--error-unmatch` exits 1 when Git tracks nothing under the path.
        Ok(output) if output.status.code() == Some(1) => Ok(()),
        Ok(output) if output.status.success() => Err(format!(
            "--source-sha names the commit of a Git-less `git archive` snapshot, but Git \
             tracks files under {}, and Git reports their commit and whether they are dirty; \
             drop --source-sha, or pass --repo-root naming the archive",
            root.display()
        )),
        Ok(output) => Err(format!(
            "--source-sha names the commit of a Git-less snapshot, but {} is inside a Git \
             checkout and `git ls-files` there failed ({}: {}), so whether Git tracks its files \
             is unknown; repair the checkout, or pass --repo-root naming an archive outside it",
            root.display(),
            output.status,
            String::from_utf8_lossy(&output.stderr).trim()
        )),
        Err(error) => Err(format!(
            "--source-sha names the commit of a Git-less snapshot, but {} is inside a Git \
             checkout and git cannot run ({error}), so whether Git tracks its files is unknown; \
             install git, or pass --repo-root naming an archive outside the checkout",
            root.display()
        )),
    }
}

fn first_attempt() -> u64 {
    1
}

/// Closed vocabulary for manifest `requires` tokens.
///
/// The optional value is the host capability whose proven absence may withhold
/// a cell. A token mapped to `None` is still validated, but can never suppress
/// execution. Keeping the mapping here gives the manifest validator and the
/// executable harness one authority.
pub const REQUIRES_VOCABULARY: &[(&str, Option<HostCapability>)] = &[
    ("ar", None),
    ("bash", None),
    ("cc", None),
    ("cpuid", Some(HostCapability::CpuidFaulting)),
    ("cxx", None),
    ("date", None),
    ("du", None),
    ("find", None),
    ("gawk", None),
    ("git", None),
    ("hexdump", None),
    ("jq", None),
    ("kvm", None),
    ("linux", None),
    ("lua5.4", None),
    ("m4", None),
    ("node", None),
    ("openssl", None),
    ("perl", None),
    ("ptrace", None),
    ("python3", None),
    ("ruby", None),
    ("rustc", None),
    ("sqlite3", None),
    ("tclsh", None),
    ("userns", None),
    // The host kernel exports `__vdso_getrandom` (Linux 6.11+ on x86-64). A
    // golden that prints the vDSO getrandom leg is only reachable on such a
    // kernel; see [`VDSO_GETRANDOM_GOLDEN_MARKER`]. Descriptive only, like
    // `cc`: nothing probes it, so on an older kernel the cell runs and fails
    // with the declared prerequisite named, instead of being withheld.
    ("vdso-getrandom", None),
    ("x86_64", None),
    ("zstd", None),
];

/// The text tests/c/random_sources.c prints only when the host kernel exports
/// `__vdso_getrandom`. On an older kernel it prints `vdso-getrandom
/// unavailable` instead, so an exact golden carrying this marker has a kernel
/// floor, and the test must declare it with the `vdso-getrandom` requires token.
pub const VDSO_GETRANDOM_GOLDEN_MARKER: &str = "vdso-getrandom[";

/// Refuse a verify golden that silently assumes a Linux 6.11+ host.
///
/// The manifest must say which host a golden was measured on when the golden
/// cannot be produced elsewhere; otherwise an older-kernel FAIL reads as a
/// determinism regression.
pub fn validate_golden_kernel_floor(
    id: &str,
    requires: &[String],
    modes: &BTreeMap<String, ModeRecipe>,
) -> Result<(), String> {
    if requires.iter().any(|token| token == "vdso-getrandom") {
        return Ok(());
    }
    for (mode, recipe) in modes {
        for (key, table) in [
            ("expected_stdout", &recipe.expected_stdout),
            ("expected_stdout_contains", &recipe.expected_stdout_contains),
        ] {
            if let Some(backend) = table.iter().find_map(|(backend, text)| {
                text.contains(VDSO_GETRANDOM_GOLDEN_MARKER)
                    .then_some(backend)
            }) {
                return Err(format!(
                    "{id}: {mode} {key}.{backend} prints the vDSO getrandom leg, which only a \
                     Linux 6.11+ host exports; declare `vdso-getrandom` in requires"
                ));
            }
        }
    }
    Ok(())
}

/// The host capability a backend itself needs, independent of any `requires`
/// token: a kvm cell cannot run where KVM is proven absent, and a cell of
/// either in-guest LiteInst backend (`liteinst`, and `in-guest-trap`, the same
/// runtime with syscall site patching off) cannot run where CPUID faulting is
/// proven absent, because that runtime arms CPUID faulting before the guest's
/// first instruction and refuses to start without it
/// (`detcore-liteinst: initialization failed: CPUID faulting is unavailable`).
///
/// Each required plan row carries this capability in
/// `requires_host_capabilities`, so the harness withholds the cell on such a
/// host, the validation planner counts it, and the Buck cell generator
/// (`ci/buck-e2e/defs.bzl`) runs it locally rather than on a remote execution
/// worker, which may lack the capability.
pub fn backend_capability(backend: &str) -> Option<HostCapability> {
    match backend {
        "kvm" => Some(HostCapability::Kvm),
        "liteinst" | "in-guest-trap" => Some(HostCapability::CpuidFaulting),
        _ => None,
    }
}

/// Whether `hermit run --strict` on `backend` reads its virtual clock from the
/// host's retired-conditional-branch counter, and so refuses where the hermit
/// binary reports no `exact_branch_counter`.
///
/// Unlike [`backend_capability`], this is decided on the machine that runs the
/// cell and never enters a plan row: a plan row that names a host capability
/// routes the cell off remote execution, and remote workers differ in CPU
/// model, so the plan cannot say which of them count exactly.
pub fn pmu_clock_backend(backend: &str) -> bool {
    matches!(backend, "ptrace" | "e9patch")
}

/// Whether the hermit binary refuses `cell` where it reports no
/// `exact_branch_counter`: the cell runs `hermit run --strict` or `hermit
/// record start --strict` on a [`pmu_clock_backend`]. Verify and chaos cells
/// always pass `--strict` to `run`, and replay cells to `record start`, which
/// refuses in the same way
/// (<https://github.com/rrnewton/hermit/issues/3810>). A custom cell passes it
/// when its arguments say so, unless they also select `--namespace-only`
/// (alias `--lite`), which arms no branch counter. A naked cell runs no
/// hermit. A run with `--max-timeslice=disabled` uses no branch count in
/// Detcore (Reverie still sets the counters up), so Hermit does not refuse it
/// (<https://github.com/rrnewton/hermit/issues/4291>):
/// not a custom cell that passes it, and not a verify cell at the relaxed
/// strictness level, which adds it ([`RELAXED_LEVEL_ARGS`]).
pub fn refused_on_an_inexact_branch_counter(cell: &SelectedCell) -> bool {
    let strict_run = match cell.id.mode.as_str() {
        "verify" | "chaos" | "replay" => true,
        "custom" => {
            let args = &cell.test.modes["custom"].args;
            let has = |flag: &str| args.iter().any(|arg| arg == flag);
            has("--strict")
                && !has("--namespace-only")
                && !has("--lite")
                && !has("--max-timeslice=disabled")
        }
        _ => false,
    };
    strict_run
        && cell.id.backend.as_deref().is_some_and(pmu_clock_backend)
        && cell.strictness_level() != Some(StrictnessLevel::Relaxed)
}

pub fn requires_capability(token: &str) -> Result<Option<HostCapability>, String> {
    REQUIRES_VOCABULARY
        .iter()
        .find(|(name, _)| *name == token)
        .map(|(_, capability)| *capability)
        .ok_or_else(|| {
            format!(
                "unknown `requires` token `{token}`; the vocabulary is closed and an unrecognized \
                 name is refused rather than treated as a reason to omit a cell"
            )
        })
}

